41	export async function generate(input: {
42	  occasion: UiOccasion;
43	  formality: number | null;
44	  /** Refine "Lean into" colour families (`COLOR_FAMILIES` keys). A preference, not a filter. */
45	  lean: string[];
46	  /** Explicit user action only — the one way to spend an AI call on a day already answered. */
47	  regenerate?: boolean;
48	  city?: { lat: number; lon: number; label: string; source: LocationSource };
49	}): Promise<GenerateResult> {
50	  try {
51	    const supabase = await createClient();
52	    const {
53	      data: { user },
54	    } = await supabase.auth.getUser();
55	    if (!user) return { status: "error", message: "Not signed in" };
56	
57	    const { data: profile } = await supabase
58	      .from("profiles")
59	      .select(
60	        "archetype, formality_min, formality_max, location_lat, location_lon, location_label, location_source, preferences",
61	      )
62	      .eq("id", user.id)
63	      .single();
64	    const { data: itemsRaw } = await supabase
65	      .from("items")
66	      .select("*")
67	      .eq("user_id", user.id)
68	      .eq("archived", false);
69	    const items = itemsRaw ?? [];
70	    const byId = new Map(items.map((i) => [i.id, i]));
71	    const pathFor = (id: string) => {
72	      const it = byId.get(id);
73	      return it ? displayPath(it) : undefined;
74	    };
75	
76	    const loc = resolveLocation({ input: input.city, profile });
77	
78	    const now = new Date();
79	    const f = await fetchForecast(loc.lat, loc.lon);
80	    const prefs = readPreferences(profile?.preferences);
81	    const advice = laterAdvice(f.hourly, prefs.tempUnit);
82	    const weather: WeatherPayload = {
83	      tempC: f.tempC,
84	      feelsLikeC: f.feelsLikeC,
85	      condition: f.condition,
86	      cityLabel: loc.label,
87	      timezone: f.timezone,
88	      locationOrigin: loc.origin,
89	      laterSentence: advice.sentence,
90	      adviceClause: advice.adviceClause,
91	      laterLabel: "Later",
92	      hourly: f.hourly,
93	      tempUnit: prefs.tempUnit,
94	    };
95	
96	    const today = localDateFor(now, f.timezone);
97	
98	    // The daily drop (Decision 5): today's looks are generated once and then
99	    // read back. Only an explicit regenerate spends an AI call on a day the
100	    // stylist has already answered.
101	    //
102	    // The stored set is read on BOTH paths. On a normal load it IS the answer;
103	    // on a regenerate it is the recency signal — the pieces the user just
104	    // rejected, which ranking will sink without ever filtering them out.
105	    const stored = await loadDailyLooks(user.id, input.occasion, today);
106	
107	    if (!input.regenerate && stored?.length) {
108	      const paths = Array.from(
109	        new Set(
110	          stored
111	            .flatMap((s) => s.pieces.map((p) => byId.get(p.itemId)))
112	            .filter((it): it is NonNullable<typeof it> => Boolean(it))
113	            .map((it) => displayPath(it)),
114	        ),
115	      );
116	      const signed = await signItemImages(paths);
117	      const looks = reassembleLooks(stored, byId, signed, pathFor);
118	      // null = the closet changed under the stored set; fall through and
119	      // regenerate rather than showing an outfit with a hole in it.
120	      if (looks) return { status: "ok", weather, looks };
121	    }
122	
123	    // Only a deliberate regenerate carries the signal. A fall-through from a
124	    // stale stored set is the app fixing itself, not the user asking for
125	    // something else — penalising those pieces would be arbitrary.
126	    const recentlyShown = input.regenerate
127	      ? Array.from(new Set(stored?.flatMap((s) => s.pieces.map((p) => p.itemId)) ?? []))
128	      : [];
129	
130	    /**
131	     * A fall-through is a DROP, not a regenerate.
132	     *
133	     * Reaching here without `input.regenerate` means either the occasion has no
134	     * looks today, or the stored set no longer reassembles because the closet
135	     * changed under it. Both are the app answering for the first time or
136	     * repairing its own bookkeeping — not the user asking again — and neither
137	     * should be charged. Drops are free on every tier regardless, so the
138	     * distinction only matters for what the ledger records.
139	     */
140	    const gen: GenerationRequest = {
141	      kind: input.regenerate ? "regenerate" : "drop",
142	      occasion: input.occasion,
143	      today,
144	    };
145	    // Caught HERE rather than in the outer catch, for two reasons: `weather` is
146	    // in scope so the screen keeps its strip instead of collapsing, and being
147	    // limited is a STATE, not a failure — routing it through the error path
148	    // would render "Couldn't reach the stylist" for a working app.
149	    try {
150	      await assertCanGenerate(user.id, gen);
151	    } catch (e) {
152	      if (e instanceof QuotaExceededError) {
153	        return { status: "limited", weather, message: e.message };
154	      }
155	      throw e;
156	    }
157	
158	    const candItems: CandidateItem[] = items.map((i) => ({
159	      id: i.id,
160	      category: i.category,
161	      colors: i.colors ?? [],
162	      formality: i.formality,
163	      seasons: i.seasons ?? [],
164	      material: i.material,
165	    }));
166	    // Occasion gives the context; the user's onboarding dress codes narrow it;
167	    // an explicit Refine formality overrides both.
168	    const band = applyFormalityOverride(
169	      personalBand(input.occasion, profile),
170	      input.formality,
171	    );
172	    const candidateArgs = {
173	      band,
174	      weather: { tempC: f.tempC, rain: f.hourly.some((h) => h.isNow && h.rain) },
175	      season: currentSeason(now),
176	      excludeItemIds: [],
177	      maxAccessories: 1,
178	      rainGuard: prefs.rainGuard,
179	    };
180	    const combos = buildCandidates(candItems, candidateArgs);
181	    if (combos.length === 0) {
182	      return { status: "empty", weather, missing: missingCategory(candItems, candidateArgs) };
183	    }
184	
185	    const aesthetic = profile?.archetype ? [profile.archetype] : [];
186	    // The Refine colour pick lands here, in ranking — not in candidate building.
187	    // It reorders the shortlist toward the requested families and is dropped
188	    // silently when the closet cannot honour it.
189	    //
190	    // Rank everything, then spread the shortlist across the wardrobe before the
191	    // re-ranker sees it. Taking the top 20 by score alone clusters — a neutral
192	    // top harmonises with everything, so it occupies most of the list, and "the
193	    // best 3" of a clustered list is three versions of one outfit. Diversifying
194	    // the INPUT makes the model's three distinct by construction.
195	    // Season rides along as a ranking preference — in-season combos float to the
196	    // top of the shortlist the re-ranker sees, but an off-season one is still
197	    // offered rather than the screen going empty.
198	    const ranked = rankTopN(
199	      combos,
200	      { aesthetic, band, lean: input.lean, recentlyShown, season: candidateArgs.season },
201	      combos.length,
202	    );
203	    const top = diversify(ranked, 20);
204	
205	    // A look the user has already worn today is PINNED: saveDailyLooks leaves it
206	    // in place, so it has to survive in what we hand back to the screen too —
207	    // otherwise the day's set silently loses it until the next page load. It
208	    // also still COUNTS toward the day's three, so the stylist is asked for
209	    // fewer fresh looks rather than the set growing a fourth tab.
210	    const pinnedStored = (stored ?? []).filter((s) => s.worn);
211	
212	    const { picks } = await rerank({
213	      want: MAX_PICKS - pinnedStored.length,
214	      combos: top.map((t) =>
215	        t.items.map((ci) => {
216	          const it = byId.get(ci.id)!;
217	          return { category: it.category, subcategory: it.subcategory, colors: it.colors ?? [] };
218	        }),
219	      ),
220	      aesthetic,
221	      occasion: input.occasion,
222	      weatherLabel: f.condition,
223	      tempC: f.tempC,
224	    });
225	
226	    const paths = Array.from(
227	      new Set([
228	        ...top.flatMap((t) => t.items.map((ci) => displayPath(byId.get(ci.id)!))),
229	        ...pinnedStored.flatMap((s) =>
230	          s.pieces.map((p) => pathFor(p.itemId)).filter((p): p is string => Boolean(p)),
231	        ),
232	      ]),
233	    );
234	    const signed = await signItemImages(paths);
235	
236	    // `rerank` already dropped picks that repeat a combo or point outside the
237	    // shortlist, so every index here resolves. It previously fell back to
238	    // `top[0]` for an unknown index, which turned a bad index into a duplicate
239	    // of the first look rather than into one fewer look.
240	    const drafts: LookDraft[] = picks.map((p) => {
241	      const combo = top[p.combo_index].items;
242	      const dbItems = combo.map((ci) => byId.get(ci.id)!);
243	      const slots = layoutForLook(dbItems.map((d) => ({ category: d.category })));
244	      const pieces: LookPiece[] = dbItems.map((d, idx) => ({
245	        itemId: d.id,
246	        category: d.category,
247	        subcategory: d.subcategory ?? null,
248	        brand: d.brand ?? null,
249	        name: d.name ?? null,
250	        colors: d.colors ?? [],
251	        cutoutUrl: signed.get(displayPath(d)) ?? "",
252	        slot: slots[idx],
253	      }));
254	      return { name: p.name, why: p.why, pieces, anchorIndex: staggerOrder(slots)[0] };
255	    });
256	
257	    // Fire-and-forget would be simpler, but a failed write means the user pays
258	    // for another AI call on their next tap — worth awaiting. The insert also
259	    // hands back the row ids, which are the detail screen's address.
260	    const ids = await saveDailyLooks(user.id, input.occasion, today, weather, drafts);
261	    const fresh: Look[] = drafts.map((d, i) => ({ ...d, id: ids[i] ?? "", worn: false }));
262	
263	    // Recorded only now — after the model answered and the write succeeded. A
264	    // generation that failed cost the user nothing, so metering it would be
265	    // charging them for our error.
266	    await noteGeneration(user.id, gen);
267	
268	    // Pinned looks keep their place at the front — they hold the lower
269	    // look_index values, which is the order the next load will read them back in.
270	    const pinned = reassembleLooks(pinnedStored, byId, signed, pathFor) ?? [];
271	
272	    return { status: "ok", weather, looks: [...pinned, ...fresh] };
273	  } catch (e) {
274	    console.error("[generate] failed:", e);
275	    return { status: "error", message: e instanceof Error ? e.message : "Generation failed" };
276	  }
277	}
