206	      name: picks[0]?.name || styledLookName(subject),
207	      why: picks[0]?.why ?? "",
208	      pieces,
209	      anchorIndex: staggerOrder(slots)[0],
210	    };
211	
212	    const outfitId = await saveStyledLook(user.id, itemId, occasion, today, weather, draft);
213	    if (!outfitId) return { status: "error", message: "Couldn't save the look" };
214	
215	    // After the model answered AND the write landed. The occasion is known by
216	    // now, which is why recording is separate from the gate above.
217	    await noteGeneration(user.id, { kind: "styled", occasion, today });
218	
219	    return { status: "ok", outfitId };
220	  } catch (e) {
221	    console.error("[styleWithItem] failed:", e);
222	    return { status: "error", message: e instanceof Error ? e.message : "Couldn't style this" };
223	  }
